INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9e72-b6b8-7861-a416-d5144be184bf'::uuid, '019f9df7-a2a2-7839-8287-1e75e9dd37f8'::uuid, 'A shopkeeper makes a loss of 24% when selling an item for $136. Find the selling price needed to make a profit of 40%.', '$250', 'If $136 is 76% of the cost price, then cost price = 136 ÷ 0.76 = 178.947... For a 40% profit, selling price = 1.4 × 178.947... = 250. So the required selling price is $250.', 'Medium', '{"tags":"percentages,profit-and-loss,money","subtopic":"profit and loss","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T12:42:25.848Z'::timestamptz, '2026-07-26T12:42:25.848Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9e72-b6bb-7080-b66e-034f8986efeb'::uuid, '019f9df7-a2a2-77cc-bb88-40ce254805a8'::uuid, 'A bag contains yellow and blue balls in the ratio 1:4. Five yellow balls are removed and 10 blue balls are added. The new ratio becomes 1:6. Find the original number of yellow balls.', '20', 'Let the original numbers be x and 4x. After the change, they become x - 5 and 4x + 10. Given (x - 5)/(4x + 10) = 1/6. So 6x - 30 = 4x + 10, hence 2x = 40 and x = 20.', 'Medium', '{"tags":"ratio,word-problem,algebra","subtopic":"changing ratios","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T12:42:25.850Z'::timestamptz, '2026-07-26T12:42:25.850Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9e72-b6c3-7306-91ea-93021d2cea00'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'Each term in a sequence is obtained by subtracting the same number from the previous term. The sequence is 78, a, b, c, 42, ... Find a, b and c.', 'a = 69, b = 60, c = 51', 'There are 4 equal steps from 78 to 42, so the common difference is (42 - 78) ÷ 4 = -9. Therefore a = 69, b = 60 and c = 51.', 'Easy', '{"tags":"algebra,sequences,arithmetic-progression","subtopic":"arithmetic sequences","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T12:42:25.859Z'::timestamptz, '2026-07-26T12:42:25.859Z'::timestamptz) ON CONFLICT (id) DO NOTHING;